from pathlib import Path

# Create a comprehensive test script that handles different memory structures
raw_path = Path.home() / ".hermes" / "mempalace" / "raw"

if raw_path.exists():
    # Initialize embedding integration
    import numpy as np
    import faiss
    from sentence_transformers import SentenceTransformer

    class MemPalaceEmbeddingIntegration:
        def __init__(self, base_path=None, embedding_model_name='all-MiniLM-L6-v2'):
            if base_path is None:
                base_path = Path.home() / ".hermes" / "mempalace"
            else:
                base_path = Path(base_path)

            self.base_path = base_path
            self.indexes_path = base_path / "indexes"
            self.id_map_path = self.indexes_path / "id_map.json"

            self.indexes_path.mkdir(parents=True, exist_ok=True)

            self.index = self._load_or_create_index()
            self.id_map = self._load_or_create_id_map()

            print(f"Loading embedding model: {embedding_model_name}")
            self.model = SentenceTransformer(embedding_model_name)

            if len(self.id_map) != self.index.ntotal:
                print(f"Warning: Index size ({self.index.ntotal}) doesn't match ID map size ({len(self.id_map)})")

            print(f"Initialized embedding integration. Index size: {self.index.ntotal}, ID map size: {len(self.id_map)}")

        def _load_or_create_index(self):
            if self.indexes_path.exists() and (self.indexes_path / "faiss.index").exists():
                print("Loading existing FAISS index...")
                return faiss.read_index(str(self.indexes_path / "faiss.index"))
            else:
                print("Creating new FAISS index...")
                return faiss.IndexFlatIP(384)

        def _load_or_create_id_map(self):
            if self.id_map_path.exists():
                with open(self.id_map_path, 'r') as f:
                    return json.load(f)
            else:
                return {}

        def extract_text_content(self, memory_data):
            """
            Extract text content from memory data, handling different structures.
            """
            # Try direct text fields
            text_fields = ['text', 'raw_text', 'content', 'body', 'message', 'summary', 'description']
            for field in text_fields:
                if field in memory_data:
                    value = memory_data[field]
                    if isinstance(value, str):
                        return value
                    elif isinstance(value, dict) and 'text' in value:
                        return value['text']
                    elif isinstance(value, list) and all(isinstance(item, str) for item in value):
                        return ' '.join(value)

            # Try payload field
            if 'payload' in memory_data and isinstance(memory_data['payload'], dict):
                payload = memory_data['payload']
                for field in text_fields:
                    if field in payload:
                        value = payload[field]
                        if isinstance(value, str):
                            return value
                        elif isinstance(value, dict) and 'text' in value:
                            return value['text']
                        elif isinstance(value, list) and all(isinstance(item, str) for item in value):
                            return ' '.join(value)

            # Try to reconstruct from memory_id and other fields
            memory_id = memory_data.get('memory_id', 'unknown')
            source_type = memory_data.get('source_type', 'unknown')

            # Fallback: return a string representation
            return f"Memory ID: {memory_id}, Source: {source_type}"

        def add_embedding(self, memory_id, text):
            embedding = self.model.encode([text], normalize_embeddings=True, convert_to_numpy=True)[0]
            vector_id = len(self.id_map)
            self.index.add(np.array([embedding]), np.array([vector_id]))
            self.id_map[str(vector_id)] = memory_id
            self._persist()
            print(f"Added embedding for memory {memory_id} (vector ID: {vector_id})")
            return vector_id

        def search_embeddings(self, query_text, k=5):
            query_embedding = self.model.encode([query_text], normalize_embeddings=True, convert_to_numpy=True)[0]
            distances, vector_ids = self.index.search(np.array([query_embedding]), k)

            results = []
            for distance, vector_id in zip(distances[0], vector_ids[0]):
                if vector_id == -1:
                    continue
                memory_id = self.id_map.get(str(vector_id))
                if memory_id is not None:
                    results.append((memory_id, float(distance)))

            return results

        def remove_embedding(self, memory_id):
            print(f"Marking embedding for removal: {memory_id}. Will be removed during nightly rebuild.")
            return True

        def _persist(self):
            faiss.write_index(self.index, str(self.indexes_path / "faiss.index"))
            with open(self.id_map_path, 'w') as f:
                json.dump(self.id_map, f, indent=2)

        def get_stats(self):
            return {
                "index_size": self.index.ntotal,
                "id_map_size": len(self.id_map),
                "index_file": str(self.indexes_path / "faiss.index"),
                "id_map_file": str(self.id_map_path)
            }

    # Create embedding integration instance
    embedding_integration = MemPalaceEmbeddingIntegration()

    # Get memory files
    memory_files = list(raw_path.glob('*.json'))[:10]
    memory_ids = [f.stem for f in memory_files]
    print(f"Found {len(memory_files)} raw memory files")

    # Add embeddings for each memory
    for memory_id in memory_ids[:5]:
        memory_file = raw_path / f"{memory_id}.json"
        if memory_file.exists():
            with open(memory_file, 'r') as f:
                memory_data = json.load(f)

            # Extract text content using the new method
            text_content = embedding_integration.extract_text_content(memory_data)

            # Add embedding
            embedding_integration.add_embedding(memory_id, text_content)

    # Test search
    print("\nTesting search functionality:")
    test_queries = [
        "What is Hermes?",
        "What is MemPalace?",
        "What is FAISS?",
        "What are embeddings?",
        "AI assistant"
    ]

    for query in test_queries:
        results = embedding_integration.search_embeddings(query, k=3)
        print(f"\nQuery: '{query}'")
        if results:
            for memory_id, score in results:
                print(f"  - {memory_id}: score={score:.4f}")
        else:
            print("  No results found")

    # Print final stats
    stats = embedding_integration.get_stats()
    print(f"\nFinal embedding integration stats:")
